-- Passage rg3-connections-p04
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('bebca98a-b85a-5989-a9a4-7f695b44a137', 'rg3-connections-p04', (select id from public.skills where slug = 'read-g3-connections'), null,
        '3-5', $q$How to Make a Pinch Pot$q$, $q$A pinch pot is a small bowl made from clay with only your hands. Artists have made pots this way for thousands of years. You can make one in art class by following these steps in order.

First, take a lump of clay about the size of an orange. Roll it between your palms until it is a smooth ball. A smooth ball has no cracks, so your pot will be strong.

Next, hold the ball in one hand. Press your thumb into the middle of the ball. Stop before your thumb goes all the way through. The bottom of the pot needs to stay thick.

Then, pinch the clay gently between your thumb and fingers. Turn the ball a little after each pinch. Keep pinching and turning. The hole will slowly grow wider, and the walls will get thinner. Try to keep the walls the same thickness all the way around. If one side is too thin, it may crack later.

After that, smooth the inside and outside with a damp finger. Let the pot dry for about a week. Clay that is still wet can break in the hot kiln.

Finally, your teacher will bake the pot in a kiln. The heat makes the clay hard. Then you can paint your pot any colors you like.$q$, 'draft')
